function countGroups(n, edges) {
  const parent = Array.from({ length: n }, (_, i) => i), size = Array(n).fill(1) //@init
  function find(x) {
    while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x] } //@hop
    return x //@root
  }
  let groups = n
  for (const [a, b] of edges) {
    let ra = find(a), rb = find(b) //@edge
    if (ra === rb) continue //@same
    if (size[ra] < size[rb]) [ra, rb] = [rb, ra] //@size
    parent[rb] = ra; size[ra] += size[rb]; groups-- //@union
  }
  return groups //@done
}

